CREATE OR REPLACE TABLE `victor-electronics-telecom21.electronics_telecom.dim_product` AS
SELECT * FROM UNNEST([
STRUCT("851761" AS hs6, "Base stations" AS description, "Base stations" AS product, "Telecom equipment" AS category),
STRUCT("851762" AS hs6, "Communication apparatus (excluding telephone sets or base stations): machines for the reception, conversion and transmission or regeneration of voice, images or other data, including switching and routing apparatus" AS description, "Switching & routing equipment" AS product, "Telecom equipment" AS category),
STRUCT("851769" AS hs6, "Communication apparatus (excluding telephone sets or base stations): machines for the transmission or reception of voice, images or other data (including wired/wireless networks), n.e.c. in item no. 8517.6" AS description, "Other communications apparatus" AS product, "Telecom equipment" AS category),
STRUCT("851770" AS hs6, "Telephone sets and other apparatus for the transmission or reception of voice, images or other data, via a wired or wireless network: parts" AS description, "Communications parts" AS product, "Telecom equipment" AS category),
STRUCT("853400" AS hs6, "Circuits: printed" AS description, "Printed circuits" AS product, "Electronic components" AS category),
STRUCT("854110" AS hs6, "Electrical apparatus: diodes, other than photosensitive or light emitting diodes" AS description, "Diodes" AS product, "Semiconductors" AS category),
STRUCT("854121" AS hs6, "Electrical apparatus: transistors, (other than photosensitive), with a dissipation rate of less than 1W" AS description, "Low-power transistors" AS product, "Semiconductors" AS category),
STRUCT("854129" AS hs6, "Electrical apparatus: transistors, (other than photosensitive), with a dissipation rate of 1W or more" AS description, "Other transistors" AS product, "Semiconductors" AS category),
STRUCT("854160" AS hs6, "Crystals: mounted piezo-electric" AS description, "Piezoelectric crystals" AS product, "Electronic components" AS category),
STRUCT("854231" AS hs6, "Electronic integrated circuits: processors and controllers, whether or not combined with memories, converters, logic circuits, amplifiers, clock and timing circuits, or other circuits" AS description, "Processors & controllers" AS product, "Integrated circuits" AS category),
STRUCT("854232" AS hs6, "Electronic integrated circuits: memories" AS description, "Memory chips" AS product, "Integrated circuits" AS category),
STRUCT("854233" AS hs6, "Electronic integrated circuits: amplifiers" AS description, "Amplifier ICs" AS product, "Integrated circuits" AS category),
STRUCT("854239" AS hs6, "Electronic integrated circuits: n.e.c. in heading no. 8542" AS description, "Other integrated circuits" AS product, "Integrated circuits" AS category),
STRUCT("854290" AS hs6, "Parts of electronic integrated circuits" AS description, "Integrated circuit parts" AS product, "Integrated circuits" AS category),
STRUCT("854420" AS hs6, "Insulated electric conductors: co-axial cable and other co-axial electric conductors" AS description, "Coaxial cables" AS product, "Connectivity" AS category),
STRUCT("854470" AS hs6, "Insulated electric conductors: optical fibre cables" AS description, "Optical fibre cables" AS product, "Connectivity" AS category)
]);
CREATE OR REPLACE TABLE `victor-electronics-telecom21.electronics_telecom.dim_year` AS
SELECT year, DATE(year,1,1) AS year_start FROM UNNEST(GENERATE_ARRAY(2012,2024)) AS year;
CREATE OR REPLACE VIEW `victor-electronics-telecom21.electronics_telecom.fact_trade` AS
SELECT year, exporter_code, importer_code, hs6,
 CAST(ROUND(value_thousand_usd * 1000, 2) AS NUMERIC) AS trade_value_usd,
 CAST(ROUND(weight_tonnes, 6) AS NUMERIC) AS weight_tonnes,
 weight_tonnes IS NOT NULL AS has_weight
FROM `victor-electronics-telecom21.electronics_telecom.baci_trade_history`;
-- Country-level concentration must not be summed or averaged across products.
-- This benchmark groups all 16 products before calculating partner shares.
CREATE OR REPLACE VIEW `victor-electronics-telecom21.electronics_telecom.country_year_benchmark` AS
WITH flows AS (
 SELECT year, importer_code AS country_code, exporter_code AS partner_code,
 'Imports' AS direction, trade_value_usd FROM `victor-electronics-telecom21.electronics_telecom.fact_trade`
 UNION ALL
 SELECT year, exporter_code, importer_code, 'Exports', trade_value_usd FROM `victor-electronics-telecom21.electronics_telecom.fact_trade`
), partner AS (
 SELECT year,country_code,direction,partner_code,SUM(trade_value_usd) AS partner_value
 FROM flows GROUP BY 1,2,3,4
), shares AS (
 SELECT *, SAFE_DIVIDE(partner_value,SUM(partner_value) OVER(PARTITION BY year,country_code,direction)) AS share
 FROM partner
), metrics AS (
 SELECT year,country_code,direction,SUM(partner_value) AS trade_value_usd,
 COUNT(*) AS partner_count,SUM(share*share)*10000 AS hhi,MAX(share) AS top_partner_share
 FROM shares GROUP BY 1,2,3
)
SELECT m.*,SAFE_DIVIDE(m.trade_value_usd,p.trade_value_usd)-1 AS yoy_growth
FROM metrics m LEFT JOIN metrics p
ON m.country_code=p.country_code AND m.direction=p.direction AND m.year=p.year+1;
ASSERT (SELECT COUNT(*) FROM `victor-electronics-telecom21.electronics_telecom.baci_trade_history`) = 1107277 AS 'Historical row count mismatch';
ASSERT (SELECT COUNT(*) FROM `victor-electronics-telecom21.electronics_telecom.baci_trade_history` f LEFT JOIN `victor-electronics-telecom21.electronics_telecom.dim_country` c ON f.importer_code=c.country_code WHERE c.country_code IS NULL)=0 AS 'Unmapped importer';
ASSERT (SELECT COUNT(*) FROM `victor-electronics-telecom21.electronics_telecom.baci_trade_history` f LEFT JOIN `victor-electronics-telecom21.electronics_telecom.dim_country` c ON f.exporter_code=c.country_code WHERE c.country_code IS NULL)=0 AS 'Unmapped exporter';
ASSERT (SELECT COUNT(*) FROM `victor-electronics-telecom21.electronics_telecom.baci_trade_history` f LEFT JOIN `victor-electronics-telecom21.electronics_telecom.dim_product` p USING(hs6) WHERE p.hs6 IS NULL)=0 AS 'Unmapped product';
SELECT year,COUNT(*) AS rows_loaded,COUNTIF(weight_tonnes IS NULL) AS missing_weight,SUM(value_thousand_usd) AS value_thousand_usd
FROM `victor-electronics-telecom21.electronics_telecom.baci_trade_history` GROUP BY year ORDER BY year;
